import numpy as np, json
from collections import deque
def f(g):
    g=np.array(g); H,W=g.shape
    vals,cnt=np.unique(g,return_counts=True); bg=int(vals[cnt.argmax()])
    out=g.copy(); seen=np.zeros((H,W),bool)
    # flood from border over background cells
    q=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i,j]==bg and not seen[i,j]: seen[i,j]=True; q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i,j]==bg and not seen[i,j]: seen[i,j]=True; q.append((i,j))
    while q:
        a,b=q.popleft()
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
            na,nb=a+da,b+db
            if 0<=na<H and 0<=nb<W and g[na,nb]==bg and not seen[na,nb]:
                seen[na,nb]=True; q.append((na,nb))
    for i in range(H):
        for j in range(W):
            if g[i,j]==bg and not seen[i,j]: out[i,j]=4
    return out.tolist()
